from fastapi import FastAPI, Body, Query
from pydantic import BaseModel, Field
from fastapi.testclient import TestClient

app = FastAPI()

class Item(BaseModel):
    name: str = Field(validation_alias="item_name")

@app.post("/items/")
async def create_item(item: Item):
    return item

@app.get("/query/")
async def read_query(q: str = Query(validation_alias="query_name")):
    return {"q": q}

client = TestClient(app)

def test_validation_alias_body():
    response = client.post("/items/", json={"item_name": "test_item"})
    assert response.status_code == 200
    assert response.json() == {"name": "test_item"}

def test_validation_alias_query():
    response = client.get("/query/", params={"query_name": "test_query"})
    assert response.status_code == 200
    assert response.json() == {"q": "test_query"}

if __name__ == "__main__":
    try:
        test_validation_alias_body()
        print("test_validation_alias_body passed")
        test_validation_alias_query()
        print("test_validation_alias_query passed")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
        exit(1)

